ScriptCommand:
triggerer.IfStat( is_hidden_monster, 0,
{
	IfStat( is_totem_object, 0,
	{
		If( this.dont_dupe != 1,
		{
			this.dont_dupe = 1;
			this.clone = CreateClone( this, copy_mods:true, disable_drops:false );
			this.clone.dont_dupe = 1;
			this.clone.SetLocation( FindRandomLocationNearLocation( 5, 25, this.GetLocation() ) );
			this.clone.AddStat( dropped_items_are_duplicated, 1 );
			this.clone.AddMonsterExplicitMod( MonsterTagMirrored );
			this.clone.PlayEffect( LakeKalandraDuplicateSpawnIn );
		} );
	} );
} );

triggerer.If( HasNamedTask( VoodooKingDeathEffigyDebuffRemoval ), (){ triggerer.RemoveNamedTask( VoodooKingDeathEffigyDebuffRemoval ); } );
triggerer.AddBuffWithOwner( voodoo_king_death_effigy_multiplying_curse, 4.5, this );
triggerer.If( VariableExists( voodoo_death_curse ), (){ triggerer.voodoo_death_curse = triggerer.voodoo_death_curse + 1; }, (){ triggerer.voodoo_death_curse = 1; } );
triggerer.AddBuff( voodoo_king_death_effigy_multiplying_curse_damage, 0.5, CalculateDamage( Clamp( Pow( 2, triggerer.voodoo_death_curse ), 1, 1500000 ), 0.01 ) );
triggerer.AddNamedDelay( VoodooKingDeathEffigyDebuffRemoval, 5.0, { triggerer.voodoo_death_curse = null; } );

Script:
If( VariableExists( chayula_skill_user ), ()
		{
			target.SpawnAttachedMonster( Metadata/Monsters/Breach/ChayulaSkills/ChayulaEnhancedFlameAuraInvisibleFire_, <root>, P, false, normal, false );
		} );
